<template><el-dialog title="服务器端口池" :visible="visible" width="820px" @close="$emit('update:visible',false)"><el-table :data="rows" v-loading="loading"><el-table-column label="环境"><template slot-scope="s">{{s.row.environmentType==='COMPETITION'?'比赛':'课程'}}</template></el-table-column><el-table-column prop="serviceType" label="工具"/><el-table-column label="起始端口"><template slot-scope="s"><el-input-number v-model="s.row.rangeStart" :min="1024" :max="65535" size="small"/></template></el-table-column><el-table-column label="结束端口"><template slot-scope="s"><el-input-number v-model="s.row.rangeEnd" :min="1024" :max="65535" size="small"/></template></el-table-column><el-table-column prop="total" label="总量"/><el-table-column prop="used" label="已用"/><el-table-column label="剩余"><template slot-scope="s"><el-tag :type="remainingPercent(s.row)<10?'danger':'success'">{{s.row.remaining}}</el-tag></template></el-table-column><el-table-column label="操作"><template slot-scope="s"><el-button type="text" @click="save(s.row)">保存</el-button></template></el-table-column></el-table><span slot="footer"><el-button @click="$emit('update:visible',false)">关闭</el-button></span></el-dialog></template>
<script>import {listAgentPortPools,updateAgentPortPool} from '@/api/ProcessingAgents';export default{props:{visible:Boolean,agentId:String},data:()=>({loading:false,rows:[]}),watch:{visible(v){if(v)this.load()}},methods:{remainingPercent(v){return v.total?Number(v.remaining||0)*100/Number(v.total):0},async load(){this.loading=true;try{const r=await listAgentPortPools(this.agentId);this.rows=r.data||[]}finally{this.loading=false}},async save(v){await updateAgentPortPool(this.agentId,v.poolId,{rangeStart:v.rangeStart,rangeEnd:v.rangeEnd});this.$message.success('端口池已保存');await this.load()}}}</script>
